preConditionHook:
// Directional: the LONG condition blocks and flattens LONGS while the close
// is below its N-bar average; the SHORT condition blocks and flattens SHORTS
// while it is above. A Switch's long condition only touches enterLong/
// exitLong (strategyWriter._switchLines), so one side can be off while the
// other trades. Flip swaps the sides (counter-trend: off for longs ABOVE the
// average). Arithmetic is CloseAboveAverage's: EL's Average recomputes fresh,
// newest-first, over the real close history.
avgClose = 0.0;
for (int i = 0; i < (int)maLength; ++i) {
    avgClose += close[i];
}
avgClose /= (int)maLength;
